const dialog=$('#detail');let previousFocus;
function showDetail(d){previousFocus=document.activeElement;$('#detail-body').innerHTML=`${d.image?`<img src="assets/${d.image}" alt="${d.title}">`:''}<div class="dialog-tag">${d.tag||''}</div><h2>${d.title}</h2><p>${d.text||''}</p>${d.items?`<ul>${d.items.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}${d.foot?`<p class="source-note">${d.foot}</p>`:''}${d.page?`<a class="dialog-link service-detail-link" href="${d.page}">사업 페이지 둘러보기 <svg class="icon-next" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></a><br>`:''}<a class="dialog-link" href="contact.html">이 프로젝트에 대해 문의하기 <svg class="icon-next" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></a>`;dialog.showModal();document.body.classList.add('modal-open');$('.dialog-close').focus()}
function closeDetail(){dialog.close()}
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');previousFocus?.focus()});$('.dialog-close').addEventListener('click',closeDetail);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail()}});$('#detail-body').addEventListener('click',e=>{if(e.target.closest('.dialog-link'))closeDetail()});
function renderWorks(filter='all'){if(!$('#work-grid'))return;$('#work-grid').innerHTML=works.map((w,i)=>({w,i})).filter(({w})=>filter==='all'||w.category===filter).map(({w,i})=>`<button class="work-card" data-work="${i}" aria-label="${w.title} 참여 경력 보기"><div class="work-image"><img src="assets/${w.image}" alt="${w.title} 프로그램 이미지" loading="lazy"></div><div class="work-meta"><span>${w.channel}</span><span>${w.label} / 참여 경력</span></div><h3>${w.title}<span><svg class="icon-next" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></span></h3></button>`).join('')}
if($('#work-grid'))renderWorks();$('#work-grid')?.addEventListener('click',e=>{const b=e.target.closest('[data-work]');if(!b)return;const w=works[Number(b.dataset.work)];showDetail({...w,tag:`${w.channel} / ${w.label}`,text:w.text,items:[`참여 경력: ${w.credit}`],foot:'출처: nPIUM 회사 소개서 7~8페이지. 대표 및 협업 작가의 참여 경력이며, nPIUM의 단독 제작 실적은 아닙니다.'})});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderWorks(b.dataset.filter)}));$$('[data-business]').forEach(b=>b.addEventListener('click',()=>showDetail({...business[b.dataset.business],page:b.dataset.business+'.html'})));$$('[data-person]').forEach(b=>b.addEventListener('click',()=>showDetail({...people[b.dataset.person],foot:'회사 소개서에 기재된 주요 경력 일부입니다.'})));$$('[data-project]').forEach(b=>b.addEventListener('click',()=>showDetail({...projects[b.dataset.project],foot:'자료 작성 당시 계획입니다. 최신 진행 상태는 문의해 주세요.'})));
function country(key){if(!$('#country-info'))return;const d=countries[key];$('#country-info').innerHTML=`<h3>${d.title}</h3><p>${d.text}</p>`}country('korea');$$('[data-country]').forEach(b=>b.addEventListener('click',()=>{$$('[data-country]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));country(b.dataset.country)}));
$('.menu').addEventListener('click',()=>{const open=$('.menu').getAttribute('aria-expanded')!=='true';$('.menu').setAttribute('aria-expanded',String(open));$('.menu').setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');$('#navigation').classList.toggle('open',open)});$$('nav a').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');$('.menu').setAttribute('aria-label','메뉴 열기')}));
$('#copy-email')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('deeperpark@gmail.com');$('#copy-status').textContent='이메일 주소를 복사했습니다.'}catch{$('#copy-status').textContent='이메일 주소를 선택해 복사해 주세요: deeperpark@gmail.com'}});
$('#inquiry')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const subject=`[nPIUM 문의] ${d.get('field')} / ${String(d.get('name')).trim()}`;const body=`이름 / 회사: ${String(d.get('name')).trim()}\n문의 분야: ${d.get('field')}\n\n${String(d.get('message')).trim()}`;window.location.href=`mailto:deeperpark@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;$('#form-status').textContent='이메일 앱에서 내용을 확인하고 전송해 주세요. 앱이 열리지 않으면 위 이메일 주소로 직접 문의해 주세요.'});
